def largestPalindrome(n: int) -> int:
    MOD = 1337
    lo = 10 ** (n - 1)
    hi = 10 ** n - 1

    # Special case for n = 1
    if n == 1:
        return 9

    # Helper to test a given palindrome p if it can be written as i * j
    # with lo <= i, j <= hi. Returns True if such a factorization exists.
    def has_factors(p: int) -> bool:
        i_min = max(lo, (p + hi - 1) // hi)  # smallest i such that p / i <= hi
        i_max = min(hi, p // lo)            # largest i such that p / i >= lo
        if i_min > i_max:
            return False
        for i in range(i_max, i_min - 1, -1):
            if p % i == 0:
                j = p // i
                if lo <= j <= hi:
                    return True
        return False

    # Try even-length palindromes of length 2n: pal = first + reverse(first)
    for first in range(hi, lo - 1, -1):
        s = str(first)
        pal = int(s + s[::-1])
        if has_factors(pal):
            return pal % MOD

    # If not found, try odd-length palindromes of length 2n-1: pal = first + reverse(first[:-1])
    for first in range(hi, lo - 1, -1):
        s = str(first)
        pal = int(s + s[:-1][::-1])
        if has_factors(pal):
            return pal % MOD

    # Should never reach here for valid inputs
    return -1

