def addOperators(num: str, target: int) -> List[str]:
    class Solution:
        def addOperators(self, num: str, target: int):
            res = []
            n = len(num)

            def dfs(index: int, path: str, value: int, prev: int):
                if index == n:
                    if value == target:
                        res.append(path)
                    return

                for i in range(index, n):
                    if i != index and num[index] == '0':
