        for j in range(sq, n + 1, sq):
            while kernel[j] % sq == 0:
                kernel[j] //= sq

    sums = defaultdict(int)
    for i in range(1, n + 1):
        sums[kernel[i]] += nums[i - 1]

    return max(sums.values()) if sums else 0

def waysToReachStair(target: int) -> int:
    if target < 0:
        return 0
    return 1 << (target + 1)

def reachingPoints(sx: int, sy: int, tx: int, ty: int) -> bool:
    # Work backwards from (tx, ty) to (sx, sy)
    while tx > sx and ty > sy:
        if tx > ty:
            tx %= ty
        else:
            ty %= tx

    # If we reached the starting point
    if tx == sx and ty == sy:
        return True

    # If one coordinate matches start and the other can be reduced by multiples of the fixed start
    if ty == sy and tx >= sx and (tx - sx) % sy == 0:
        return True
    if tx == sx and ty >= sy and (ty - sy) % sx == 0:
        return True

    return False

def kthCharacter( k: int, operations: List[int]) -> str:
    shift = 0  # number of times we applied the "next character" transform
    m = len(operations)

    # Work backwards from the last operation to the first
    for i in range(m - 1, -1, -1):
        half_len = 1 << i  # length of the string before operation i (2^i)
        if k > half_len:
            # We are in the second half produced by operation i
            if operations[i] == 1:
                shift = (shift + 1) % 26
            k -= half_len  # map k to the corresponding position in the first half

    # After processing all operations, the character is 'a' advanced by `shift`
    return chr(ord('a') + (shift % 26))

def calculate(s: str) -> int:
    class Solution:
        def calculate(self, s: str) -> int:
            stack = []
            result = 0
            number = 0
            sign = 1  # 1 for '+', -1 for '-'
            for ch in s:
                if ch.isdigit():
                    number = number * 10 + int(ch)
                elif ch == '+':
                    result += sign * number
                    number = 0
                    sign = 1
                elif ch == '-':
                    result += sign * number
                    number = 0
                    sign = -1
                elif ch == '(':
                    stack.append(result)
                    stack.append(sign)
                    result = 0
                    sign = 1
                elif ch == ')':
                    result += sign * number
                    number = 0
                    sign = stack.pop()
                    prev = stack.pop()
                    result = prev + sign * result
                else:
                    pass  # skip spaces or any other characters
            result += sign * number
            return result
    return Solution().calculate(s)

def consecutiveNumbersSum(n: int) -> int:
    if n <= 0:
        return 0

    # Remove all factors of 2 from n
    m = n
    while m % 2 == 0:
        m //= 2

    # Count the divisors of the odd part m
    count = 1
    temp = m
    d = 3
    while d * d <= temp:
        if temp % d == 0:
            exp = 0
            while temp % d == 0:
                temp //= d
                exp += 1
            count *= (exp + 1)
        d += 2

    if temp > 1:
        count *= 2

    return count

def maximumScore(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    if n == 0 or k <= 0:
        return 1

    maxVal = max(nums)

    # Sieve for smallest prime factor (spf)
    spf = [0] * (maxVal + 1)
    for i in range(2, maxVal + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= maxVal:
                for j in range(i * i, maxVal + 1, i):
                    if spf[j] == 0:
                        spf[j] = i
    for i in range(2, maxVal + 1):
        if spf[i] == 0:
            spf[i] = i

    # Distinct prime factor count for each nums[i]
    s = [0] * n
    for i, v in enumerate(nums):
        x = v
        cnt = 0
        while x > 1:
            p = spf[x]
            cnt += 1
            while x % p == 0:
                x //= p
        s[i] = cnt

    # Next greater element to the right based on s
    nextGreater = [n] * n
    stack = []
    for i in range(n):
        while stack and s[i] > s[stack[-1]]:
            idx = stack.pop()
            nextGreater[idx] = i
        stack.append(i)

    freq = [nextGreater[i] - i for i in range(n)]

    # Build (value, available_count) pairs
    pairs = list(zip(nums, freq))
    pairs.sort(key=lambda x: x[0], reverse=True)

    # Take up to k multipliers with largest values
    ans = 1
    rem = k
    for val, cnt in pairs:
        if rem <= 0:
            break
        take = min(cnt, rem)
        ans = (ans * pow(val, take, MOD)) % MOD
        rem -= take

    return ans

def maxIncreasingGroups(usageLimits: List[int]) -> int:
    total = sum(usageLimits)
    hi = int(((1 + 8 * total) ** 0.5 - 1) // 2)
    lo = 0

    while lo < hi:
        mid = (lo + hi + 1) // 2
        need = mid * (mid + 1) // 2
        s = 0
        for a in usageLimits:
            s += a if a < mid else mid
            if s >= need:
                break
        if s >= need:
            lo = mid
        else:
            hi = mid - 1

    return lo

def countOfPairs(nums: List[int]) -> int:
    MOD = 10**9 + 7
    if not nums:
        return 0

    # dp for i=0: a0 can be any value in [0, nums[0]]
    prev = [1] * (nums[0] + 1)

    for i in range(1, len(nums)):
        m = nums[i]
        # min increment for a[i] given a[i-1] to maintain non-decreasing a and non-increasing b
        min_step = max(0, nums[i] - nums[i - 1])

        # prefix sums of prev to quickly compute sums up to limit
        pref = [0] * len(prev)
        s = 0
        for idx in range(len(prev)):
            s = (s + prev[idx]) % MOD
            pref[idx] = s

        cur = [0] * (m + 1)
        for x in range(0, m + 1):
            limit = x - min_step
            if limit < 0:
                cur[x] = 0
            else:
                if limit >= len(prev) - 1:
                    cur[x] = pref[-1]
                else:
                    cur[x] = pref[limit]

        prev = cur

    return sum(prev) % MOD

def kMirror(k: int, n: int) -> int:
    if n <= 0:
        return 0

    def _digits(num: int, length: int, base: int) -> list:
        digits = [0] * length
        for i in range(length - 1, -1, -1):
            digits[i] = num % base
            num //= base
        return digits

    total = 0
    count = 0

    # Length L = 1
    for d in range(1, k):  # digits 1..k-1
        total += d
        count += 1
        if count == n:
            return total

    L = 2
    while count < n:
        if L % 2 == 0:
            # Even length L = 2*m
            m = L // 2
            rest_len = max(0, m - 1)  # number of free digits after the leading digit in the first half
            for d0 in range(1, k):  # leading digit cannot be zero
                if count == n:
                    return total
                if rest_len == 0:
                    digits = [d0]
                    pal = digits + digits[::-1]
                    val = 0
                    for dig in pal:
                        val = val * k + dig
                    total += val
                    count += 1
                    if count == n:
                        return total
                else:
                    for rest in range(k ** rest_len):
                        digits = [d0] + _digits(rest, rest_len, k)
                        pal = digits + digits[::-1]
                        val = 0
                        for dig in pal:
                            val = val * k + dig
                        total += val
                        count += 1
                        if count == n:
                            return total
        else:
            # Odd length L = 2*m + 1
            m = (L - 1) // 2
            h = m + 1  # first half length
            rest_len = h - 1
            for d0 in range(1, k):
                if count == n:
                    return total
                for rest in range(k ** rest_len):
                    first_half = [d0] + _digits(rest, rest_len, k)
                    pal = first_half + first_half[:-1][::-1]
                    val = 0
                    for dig in pal:
                        val = val * k + dig
                    total += val
                    count += 1
                    if count == n:
                        return total
        L += 1

    return total

def minimumDistance(points0: List[List[int]]) -> int:
    points = points0
    n = len(points)
    s = [x + y for x, y in points]
    d = [x - y for x, y in points]

    Smax1Val = -10**20
    Smax1Count = 0
    Smax2Val = -10**20
    for val in s:
        if val > Smax1Val:
            Smax2Val = Smax1Val
            Smax1Val = val
            Smax1Count = 1
        elif val == Smax1Val:
            Smax1Count += 1
        elif val > Smax2Val:
            Smax2Val = val

    Smin1Val = 10**20
    Smin1Count = 0
    Smin2Val = 10**20
    for val in s:
        if val < Smin1Val:
            Smin2Val = Smin1Val
            Smin1Val = val
            Smin1Count = 1
        elif val == Smin1Val:
            Smin1Count += 1
        elif val < Smin2Val:
            Smin2Val = val

    Dmax1Val = -10**20
    Dmax1Count = 0
    Dmax2Val = -10**20
    for val in d:
        if val > Dmax1Val:
            Dmax2Val = Dmax1Val
            Dmax1Val = val
            Dmax1Count = 1
        elif val == Dmax1Val:
            Dmax1Count += 1
        elif val > Dmax2Val:
            Dmax2Val = val

    Dmin1Val = 10**20
    Dmin1Count = 0
    Dmin2Val = 10**20
    for val in d:
        if val < Dmin1Val:
            Dmin2Val = Dmin1Val
            Dmin1Val = val
            Dmin1Count = 1
        elif val == Dmin1Val:
            Dmin1Count += 1
        elif val < Dmin2Val:
            Dmin2Val = val

    ans = 10**30
    for i in range(n):
        if s[i] == Smax1Val and Smax1Count == 1:
            max_s_excl = Smax2Val
        else:
            max_s_excl = Smax1Val

        if s[i] == Smin1Val and Smin1Count == 1:
            min_s_excl = Smin2Val
        else:
            min_s_excl = Smin1Val

        span_s = max_s_excl - min_s_excl

        if d[i] == Dmax1Val and Dmax1Count == 1:
            max_d_excl = Dmax2Val
        else:
            max_d_excl = Dmax1Val

        if d[i] == Dmin1Val and Dmin1Count == 1:
            min_d_excl = Dmin2Val
        else:
            min_d_excl = Dmin1Val

        span_d = max_d_excl - min_d_excl

        val = max(span_s, span_d)
        if val < ans:
            ans = val

    return ans
